export interface Attraction {
  name: string;
  description: string;
  wikiTitle: string;
  type: "landmark" | "nature" | "museum" | "beach" | "city" | "heritage" | "temple";
  visitDuration: string;
}

export interface CountryTouristInfo {
  tagline: string;
  bestTimeToVisit: string;
  currency: string;
  language: string;
  capital: string;
  timezone: string;
  attractions: Attraction[];
}

export interface VisaDetail {
  feeUSD: number | null;
  processingDays: string;
  maxStay: string;
  documents: string[];
  process: string[];
  onlineApplyUrl?: string;
  notes?: string;
}

