export function getCountryTouristInfo(code: string): CountryTouristInfo | null {
  return touristData[code] ?? null;
}

export function getVisaDetailForRoute(passport: string, destination: string, requirement: string): VisaDetail {
  return getVisaDetail(passport, destination, requirement);
}
